    "/api/Trips/import": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        get?: never;
        put?: never;
        /**
         * Stores a chunk of a broker's CSV file in one request.
         * @description Answers per row, so read <i>Results</i> rather than the status code alone: a rejected
         *     row stores nothing and does not stop the rest of the chunk. Each carries an
         *     <i>ErrorCode</i>, a message saying what to fix in the file, a <i>Retryable</i> flag and
         *     a <i>CorrelationId</i> for support.
         *
         *     <br>
         *     Re-sending a chunk is safe: rows are matched on the broker's own TripId, so a trip
         *     that already went in is updated rather than duplicated. That is what lets the client
         *     retry a chunk the shared host refused without the office having to work out which
         *     half of the file arrived.
         */
        post: {
            parameters: {
                query?: never;
                header?: never;
                path?: never;
                cookie?: never;
            };
            requestBody?: {
                content: {
                    "application/json": components["schemas"]["TripImportRequestDto"];
                    "text/json": components["schemas"]["TripImportRequestDto"];
                    "application/*+json": components["schemas"]["TripImportRequestDto"];
                };
            };
            responses: {
                /** @description Every row in the chunk was stored. */
                200: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "text/plain": components["schemas"]["TripImportResultDto"];
                        "application/json": components["schemas"]["TripImportResultDto"];
                        "text/json": components["schemas"]["TripImportResultDto"];
                    };
                };
                /** @description Some rows were stored and some were rejected. See Results. */
                207: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "text/plain": components["schemas"]["TripImportResultDto"];
                        "application/json": components["schemas"]["TripImportResultDto"];
                        "text/json": components["schemas"]["TripImportResultDto"];
                    };
                };
                /** @description The chunk is empty, or names a funding source that does not exist. */
                400: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "text/plain": components["schemas"]["ProblemDetails"];
                        "application/json": components["schemas"]["ProblemDetails"];
                        "text/json": components["schemas"]["ProblemDetails"];
                    };
                };
                /** @description Every row in the chunk was rejected. See Results. */
                422: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "text/plain": components["schemas"]["TripImportResultDto"];
                        "application/json": components["schemas"]["TripImportResultDto"];
                        "text/json": components["schemas"]["TripImportResultDto"];
                    };
                };
            };
        };
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
